#!/usr/bin/env python3
"""Figure 6 (the paper's fig1_basin), regenerated by LIEP-REGEN with the corrected lock-in.

Revision of 2026-11-13 (owner's choices): the (omega_p, eps) map is replaced by fidelity curves, because its eps rows
agree to within FigEpsSpreadIn up to omega_p 0.2 in a noiseless simulation; the training panel, cleaned of the pre-fix
and integrator-step diagnostics, becomes the main result; (c) gains the LIEP-BASE linear controls.

(a) layer-1 gradient fidelity against omega_p: the untrained grid network at eps 0.03 (quartile band) and 0.003;
    kappa and cos 0.9 marked (no trained-network curve: owner, 2026-11-13).
(b) training from scratch at the probe points (corrected lock-in, eps 0.03): final accuracy (top) and the hidden
    layer's gain under a linear probe over its random start (bottom); the training edge shaded.
(c) four networks from scratch, each at its rule (owner, 2026-11-16; LIEP-6C): the backprop networks with Muon
    (their best result: backprop is non-local anyway and shows the architecture's capacity), the EP arms with the local
    matched rule (Adam + cosine, layer 2 at kappa 0.1; lock-in with amplitude homeostasis, its hardware form); the
    linear probe on each phasor arm's hidden layer; logistic regression on the raw pixels and the phase-encoded input.
    The full rule x network grid is the appendix table data/fig6c_table.tex.

Every number is read from figures/data/, written by figures/export.py. Every omega_p axis is linear in log10(omega_p).
History: the 2026-11-05 version (map + failure strip + diagnostic (d)) is in git.
"""
import sys
from pathlib import Path

import numpy as np
import plotly.graph_objects as go
from plotly.subplots import make_subplots

sys.path.insert(0, str(Path(__file__).resolve().parent))
import liepfig as L

# NOTE (from the original): add_hline/add_vline/add_hrect/add_vrect default to exclude_empty_subplots=True when given
# row/col, so a shape aimed at a subplot with no traces YET is silently dropped. Always pass exclude_empty_subplots=False.

M = L.macros("fig6")
fid = L.dat("fig6_fid.dat")
pts = L.dat("fig6_points.dat")
cmp_ = L.dat("fig6_c.dat")
cprobe = L.dat("fig6_cprobe.dat")
base = L.dat("fig6_base.dat")
lg = np.log10

KAPPA = float(M["FigKappa"])
ELO, EHI = float(M["FigEdgeLo"]), float(M["FigEdgeHi"])

# ------------------------------------------------------------ layout budget
ML, MR, MT, MB = 46.0, 4.0, 16.0, 31.0
(D_FID, D_ACC, D_GAIN), PLOT_H = L.vstack(
    heights=[70.0, 66.0, 40.0],
    gaps=[38.0, 4.0])                         # the first gap holds (a)'s x labels and (b)'s heading
LEFT = [0.0, 0.565]                           # every omega_p panel shares this column, so x lines up top to bottom
RIGHT = [0.705, 1.0]
TOTAL = MT + PLOT_H + MB
PT = 1.0 / PLOT_H
D_CMP = [D_ACC[0] + 20.0 * PT, D_FID[1]]      # (c) spans (a) and most of (b)'s accuracy row; its key sits below it

# Row-major axes: fidelity x1, comparison x2, accuracy x3, (unused x4), gain x5, (unused x6).
fig = make_subplots(rows=3, cols=2)
XR = [lg(0.0034), lg(2.9)]
TICKS = [0.005, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5, 1, 2]
TICKT = ["0.005", "0.01", "0.02", "0.05", "0.1", "0.2", "0.5", "1", "2"]
FS = L.pt(5.5)

# ------------------------------------------------------- (a) fidelity curves
fig.add_hline(y=0.9, line=dict(color=L.GRAY, width=L.pt(0.5), dash="dash"), layer="below",
              row=1, col=1, exclude_empty_subplots=False)
fig.add_hline(y=0.0, line=dict(color=L.GRAY, width=L.pt(0.4)), layer="below", row=1, col=1, exclude_empty_subplots=False)
fig.add_vline(x=lg(KAPPA), line=dict(color=L.GRAY, width=L.pt(0.5), dash="dot"), layer="below",
              row=1, col=1, exclude_empty_subplots=False)
fig.add_annotation(x=lg(KAPPA), y=-0.95, xref="x", yref="y", text="&#954;", showarrow=False,
                   xanchor="left", xshift=L.pt(1.5), yanchor="bottom", font=dict(size=L.pt(6.5), color=L.GRAY))
fig.add_annotation(x=lg(2.9), y=0.9, xref="x", yref="y", text="cos 0.9", showarrow=False,
                   xanchor="right", yanchor="bottom", font=dict(size=FS, color=L.GRAY))

CURVES = [("syn_e0.03", L.HOLO, "solid", 1.1, True, "&#949; 0.03"),
          ("syn_e0.003", L.PROBE, "dash", 0.9, False, "&#949; 0.003")]
for tag, colour, dash, w, band, _ in CURVES:
    c = fid[fid.curve == tag].sort_values("omega_p")
    if band:
        fig.add_trace(go.Scatter(
            x=np.concatenate([lg(c.omega_p), lg(c.omega_p)[::-1]]), y=np.concatenate([c.q75, c.q25[::-1]]),
            mode="lines", fill="toself", fillcolor=L.rgba(colour, 0.15), line=dict(width=0), hoverinfo="skip"), row=1, col=1)
    fig.add_trace(go.Scatter(x=lg(c.omega_p), y=c.med, mode="lines+markers",
                             line=dict(color=colour, width=L.pt(w), dash=dash),
                             marker=dict(size=L.pt(2.4), color=colour), hoverinfo="skip"), row=1, col=1)
# key in the empty lower left of (a)
for k, (tag, colour, dash, w, band, txt) in enumerate(CURVES):
    y = -0.30 - 0.27 * k
    fig.add_shape(type="line", x0=lg(0.0042), x1=lg(0.0065), y0=y, y1=y, xref="x", yref="y",
                  line=dict(color=colour, width=L.pt(w), dash=dash))
    fig.add_annotation(x=lg(0.0072), y=y, xref="x", yref="y", text=txt, showarrow=False,
                       xanchor="left", yanchor="middle", font=dict(size=FS, color="black"))

# --------------------------------------------- (b) accuracy and hidden-layer gain at the training points
for row in (2, 3):
    fig.add_vrect(x0=lg(ELO), x1=lg(EHI), fillcolor=L.rgba(L.BAD, 0.13), line_width=0, layer="below",
                  row=row, col=1, exclude_empty_subplots=False)
fig.add_hline(y=0, line=dict(color=L.GRAY, width=L.pt(0.5)), row=3, col=1, exclude_empty_subplots=False)

line = pts[(pts.kind == "corrected") & (pts.eps == 0.03) & (pts.open == 0)].sort_values("omega_p")
for yrow, col, lo, hi, xa, ya in ((2, "acc", "acclo", "acchi", "x3", "y3"), (3, "gain", "gainlo", "gainhi", "x5", "y5")):
    fig.add_trace(go.Scatter(
        x=lg(line.omega_p), y=line[col], mode="lines+markers",
        line=dict(color=L.HOLO, width=L.pt(0.9)),
        error_y=dict(type="data", symmetric=False, array=line[hi] - line[col], arrayminus=line[col] - line[lo],
                     thickness=L.pt(0.6), width=0, color=L.HOLO),
        marker=dict(size=L.pt(4.2), color=L.HOLO, line=dict(color=L.HOLO, width=L.pt(0.8))),
        hoverinfo="skip"), row=yrow, col=1)
    if yrow == 2:
        for _, p in line.iterrows():
            fig.add_annotation(x=lg(p.omega_p), y=p[col], xref=xa, yref=ya, text=p.label, showarrow=False,
                               xanchor="left", xshift=L.pt(3.0), yanchor="bottom", yshift=L.pt(0.5),
                               font=dict(size=FS, color=L.HOLO))
fig.add_annotation(x=lg(np.sqrt(ELO * EHI)), y=0.40, xref="x3", yref="y3", text="hidden<br>layer stops<br>learning",
                   showarrow=False, xanchor="center", yanchor="bottom", font=dict(size=FS, color=L.BAD))
fig.add_annotation(x=lg(0.0045), y=-0.003, xref="x5", yref="y5", text=f"random start ({M['FigProbeRandom']})",
                   showarrow=False, xanchor="left", yanchor="top", font=dict(size=FS, color=L.GRAY))

# ------------------------------- (c) from scratch, with the linear controls
CMP_ARMS = [("relu", "ReLU<br>MLP", L.GRAY, False), ("phasor_bp", "phasor<br>BP", L.HOLO, True),
            ("lockin", "lock-in<br>EP", L.ANTIHOLO, True), ("centred", "centred<br>EP", L.HEBB, True)]
XC = [-0.6, 3.75]
for model, txt, dash in (("pixels", f"LR, pixels {M['FigLRPixels']}", "dot"),
                         ("phase", f"LR, phase-encoded<br>input {M['FigLRPhase']}", "dash")):
    r = base[(base.kind == "logreg") & (base.model == model)].iloc[0]
    fig.add_shape(type="rect", x0=XC[0], x1=XC[1], y0=r.lo, y1=r.hi, line=dict(width=0),
                  fillcolor=L.rgba(L.GRAY, 0.10), layer="below", row=1, col=2)
    fig.add_shape(type="line", x0=XC[0], x1=XC[1], y0=r.med, y1=r.med, layer="below",
                  line=dict(color=L.GRAY, width=L.pt(0.7), dash=dash), row=1, col=2)
    fig.add_annotation(x=XC[0] + 0.05, y=r.lo, xref="x2", yref="y2", text=txt, showarrow=False,   # below the band, left,
                       xanchor="left", yanchor="top", align="left", font=dict(size=FS, color=L.GRAY))     # clear of every run
JIT = np.random.default_rng(11)
for k, (arm, _lab, colour, probe) in enumerate(CMP_ARMS):
    v = cmp_[cmp_.arm == arm].acc.values
    xc = k - (0.12 if probe else 0.0)
    fig.add_trace(go.Scatter(
        x=xc + JIT.uniform(-0.13, 0.13, len(v)), y=v, mode="markers",
        marker=dict(size=L.pt(1.9), color=L.rgba(colour, 0.75), line=dict(width=0)),
        hoverinfo="skip"), row=1, col=2)
    m, sd = v.mean(), v.std(ddof=1)
    fig.add_shape(type="rect", x0=xc - 0.24, x1=xc + 0.24, y0=m - sd, y1=m + sd, line=dict(width=0),
                  fillcolor=L.rgba(colour, 0.14), layer="below", row=1, col=2)
    fig.add_shape(type="line", x0=xc - 0.24, x1=xc + 0.24, y0=m, y1=m,
                  line=dict(color=colour, width=L.pt(1.3)), row=1, col=2)
    if probe:
        r = cprobe[cprobe.arm == arm].iloc[0]
        fig.add_trace(go.Scatter(
            x=[k + 0.30], y=[r.med], mode="markers",
            error_y=dict(type="data", symmetric=False, array=[r.hi - r.med], arrayminus=[r.med - r.lo],
                         thickness=L.pt(0.6), width=0, color=colour),
            marker=dict(size=L.pt(4.0), symbol="diamond-open", color=colour, line=dict(color=colour, width=L.pt(0.9))),
            hoverinfo="skip"), row=1, col=2)

# (c)'s two groups: backprop at its best rule, EP at the local matched rule
fig.add_shape(type="line", x0=1.5, x1=1.5, y0=0, y1=1, yref="y2 domain", layer="below",
              line=dict(color=L.GRAY, width=L.pt(0.4), dash="dot"), row=1, col=2)
for xg, txt in ((0.5, "backprop, Muon"), (2.5, "EP, local rule")):
    fig.add_annotation(x=xg, y=1.0, xref="x2", yref="y2 domain", text=txt, showarrow=False, xanchor="center",
                       yanchor="top", font=dict(size=FS, color=L.GRAY))

# (c)'s key, below its tick labels
KEY_Y0 = D_ACC[0] - 2.0 * PT
fig.add_annotation(x=RIGHT[0], y=KEY_Y0, xref="paper", yref="paper", align="left", showarrow=False,
                   xanchor="left", yanchor="top", font=dict(size=FS, color=L.GRAY),
                   text="dots: runs; bar: mean &#177; 1 s.d.<br>"
                        "&#9671;: linear probe on the trained<br>hidden layer (min&#8211;max, " + M["FigCN"] + " seeds)<br>"
                        "lines: logistic regression (LR)<br>on the network's input")

# --------------------------------------------------------------- axes
fig.update_layout(**L.layout(TOTAL, margin=dict(l=L.pt(ML), r=L.pt(MR), t=L.pt(MT), b=L.pt(MB))))
fig.update_xaxes(L.AXIS, range=XR, tickvals=lg(TICKS), ticktext=TICKT,
                 title_text="probe frequency&#8201; &#969;<sub>p</sub>", title_standoff=L.pt(2), domain=LEFT, row=1, col=1)
fig.update_yaxes(L.AXIS, range=[-1.08, 1.08], tickvals=[-1, -0.5, 0, 0.5, 1], ticktext=["−1", "−0.5", "0", "0.5", "1"],
                 title_text="cosine to exact", title_standoff=L.pt(3), domain=D_FID, row=1, col=1)

lo_ = min(cmp_.acc.min(), base[base.kind == "logreg"].lo.min()) - 0.0045
hi_ = max(cmp_.acc.max(), cprobe.hi.max()) + 0.0065                          # room for the group labels
fig.update_xaxes(L.AXIS, range=XC, tickvals=[0, 1, 2, 3], ticktext=[a[1] for a in CMP_ARMS], ticks="",
                 showline=False, tickangle=0, tickfont=dict(size=L.pt(6.0)), domain=RIGHT, row=1, col=2)
fig.update_yaxes(L.AXIS, range=[lo_, hi_], tickvals=[0.84, 0.85, 0.86, 0.87, 0.88, 0.89, 0.90], tickformat=".2f",
                 title_text="test accuracy", title_standoff=L.pt(2), domain=D_CMP, row=1, col=2)

fig.update_xaxes(L.AXIS, range=XR, tickvals=lg(TICKS), ticktext=[""] * len(TICKS), domain=LEFT, row=2, col=1)
fig.update_yaxes(L.AXIS, range=[0.33, 0.93], tickvals=[0.4, 0.6, 0.8], title_text="test accuracy",
                 title_standoff=L.pt(3), domain=D_ACC, row=2, col=1)
fig.update_xaxes(L.AXIS, range=XR, tickvals=lg(TICKS), ticktext=TICKT,
                 title_text="probe frequency&#8201; &#969;<sub>p</sub>", title_standoff=L.pt(2), domain=LEFT, row=3, col=1)
fig.update_yaxes(L.AXIS, range=[-0.062, 0.03], tickvals=[-0.06, -0.03, 0, 0.02],
                 ticktext=["−0.06", "−0.03", "0", "+0.02"], title_text="hidden-layer<br>gain", title_standoff=L.pt(3),
                 domain=D_GAIN, row=3, col=1)
for r, dom in ((2, D_ACC), (3, D_GAIN)):
    # invisible axes, kept inside their own corner: a subplot's white background would hide anything beneath it
    fig.update_xaxes(visible=False, range=[0, 1], domain=RIGHT, row=r, col=2)
    fig.update_yaxes(visible=False, range=[0, 1], domain=[dom[0], dom[0] + 0.01], row=r, col=2)

L.panel_label(fig, 0.0, D_FID[1] + 0.012, "a", "Gradient fidelity, layer 1")
L.panel_label(fig, RIGHT[0] - 0.06, D_FID[1] + 0.012, "c", "From scratch")
L.panel_label(fig, 0.0, D_ACC[1] + 4.0 * PT, "b", "Training at each probe frequency, &#949; 0.03")

L.save(fig, "fig6_basin")
